package com.collabboard.security;
import com.collabboard.auth.AppUserRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Component public class JwtCookieFilter extends OncePerRequestFilter {private final JwtService jwt;private final AppUserRepository users;public JwtCookieFilter(JwtService jwt,AppUserRepository users){this.jwt=jwt;this.users=users;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{if(req.getCookies()!=null)for(Cookie c:req.getCookies())if("COLLABBOARD_SESSION".equals(c.getName()))try{AuthPrincipal p=jwt.parse(c.getValue());if(users.findById(p.id()).filter(u->u.getTokenVersion()==p.tokenVersion()).isPresent())SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,java.util.List.of()));}catch(RuntimeException ignored){}chain.doFilter(req,res);}}
